@patch.multiple(RadioRackAttenuator, _write=Mock(), _make_sure_port_has_correct_value=Mock())
def test_method_set_single_path_attenuation_constructs_correct_command_for_radiorack(radiorack_object):
    rf_path_to_reserve = 1
    attenuation_value = 40
    expected_command = "ATT {} {}".format(rf_path_to_reserve, attenuation_value)
    expected_call = [call(expected_command)]
    radiorack_object.reserve_port(rf_path_to_reserve)
    radiorack_object._set_single_rf_path_decibel_attenuation(rf_path_to_reserve, attenuation_value)
    radiorack_object._write.assert_has_calls(expected_call)


def test_reading_attenuation_value_of_rf_path_for_radiorack_success(radiorack_object):
    att_output = "ATT 1 0;ATT 2 0;ATT 3 111;ATT 4 120;ATT 5 120;ATT 6 120;ATT 7 120;ATT 8 120;ATT 9 120;ATT 10 120;" \
            "ATT 11 220;ATT 12 220;ATT 13 220;ATT 14 220;ATT 15 220;ATT 16 220"
    radiorack_object.telnet.read_command = Mock(return_value=att_output)
    retrieved_value = radiorack_object._read_value_of_rf_path(3)
    assert retrieved_value == '111'


def test_reading_attenuation_value_of_nonexistent_rf_path_on_radiorack_causes_exception(radiorack_object):
    att_output = "ATT 1 0;ATT 2 0;ATT 3 120;ATT 4 120;ATT 5 120;ATT 6 120;ATT 7 120;ATT 8 120;ATT 9 120;ATT 10 120;" \
            "ATT 11 220;ATT 12 220;ATT 13 220;ATT 14 220;ATT 15 220;ATT 16 220"
    radiorack_object.telnet.read_command = Mock(return_value=att_output)
    with pytest.raises(ReadingAttenuationValueOfNonexistentRFPath):
        radiorack_object._read_value_of_rf_path(17)


def test_attenuation_value_other_than_desired_on_radiorack_causes_exception(radiorack_object):
    desired_value = 40
    actual_value = 30
    radiorack_object._read_value_of_rf_path = Mock(return_value=actual_value)
    with pytest.raises(AttenuationValueIsOtherThanExpected):
        radiorack_object._make_sure_port_has_correct_value(1, desired_value, True)


@pytest.fixture()
def radiorack_object():
    min_attenuation = 0
    max_attenuation = 60
    ip = '127.0.0.1'
    attenuator_object = RadioRackAttenuator(min_attenuation, max_attenuation, ip)
    return attenuator_object
